"""index.html is generated by scripts/build_landing_page.py — keep them in sync.

The landing page's data-sources list is derived from the viewer's VARIABLES /
VAR_SOURCES / SOURCE_NAMES tables. Change a variable in the viewer without
rebuilding the landing page and the public site lists sources the map no
longer uses (the hand-written page advertised "extreme-heat days" long after
that variable was dropped).

The generator imports build_diy_pca_viewer, which pulls in geopandas/xarray,
so this skips on the CI deploy gate (pytest + stdlib only) and runs in the
socal-heat env.
"""

import re
import sys

import pytest


@pytest.fixture(scope="module")
def landing(project_root):
    sys.path.insert(0, str(project_root / "scripts"))
    # Skip on the viewer's heavy imports only — a missing build_landing_page
    # must fail, not skip.
    pytest.importorskip("build_diy_pca_viewer", reason="needs the socal-heat env (geopandas, xarray)")
    import build_landing_page

    return build_landing_page


def test_index_html_matches_generator(project_root, landing):
    committed = (project_root / "index.html").read_text(encoding="utf-8")
    assert committed == landing.render(), (
        "index.html is stale — run `python3 scripts/build_landing_page.py` "
        "and commit the result. Edit HTML_TEMPLATE in that script, not index.html."
    )


def test_every_viewer_variable_is_counted_once(landing):
    """A variable under a pillar key the page doesn't list would silently drop off."""
    listed = sum(n for _, rows in landing.source_groups() for _, _, n in rows)
    assert listed == len(landing.VARIABLES)


def _cff_field(project_root, key):
    text = (project_root / "CITATION.cff").read_text(encoding="utf-8")
    m = re.search(rf"^{key}:\s*'?([^'\n]+?)'?\s*$", text, re.MULTILINE)
    assert m, f"CITATION.cff has no top-level {key}:"
    return m.group(1)


@pytest.mark.parametrize("page", ["index.html", "README.md", "main/heat_risk_map.html"])
def test_citation_matches_citation_cff(project_root, page):
    """The copy-paste citations hand-repeat CITATION.cff's DOI and version; a release bump must update them."""
    text = (project_root / page).read_text(encoding="utf-8")
    assert f"https://doi.org/{_cff_field(project_root, 'doi')}" in text
    assert f"Version {_cff_field(project_root, 'version')}" in text
